import { render } from '@solidjs/web';
import { createSignal, onSettled, Switch, Match } from 'solid-js';

function App() {
  const [route, setRoute] = createSignal('home');
  onSettled(() => {
    const update = () => setRoute(location.hash.slice(1) || 'home');
    update();
    window.addEventListener('hashchange', update);
    return () => window.removeEventListener('hashchange', update);
  });
  return (
    <>
      <nav>
        <a href="#home">Home</a> | <a href="#profile">Profile</a> |{' '}
        <a href="#settings">Settings</a>
      </nav>
      <Switch fallback={<h1>Page not found</h1>}>
        <Match when={route() === 'home'}>
          <h1>Welcome to this Simple Routing Example</h1>
        </Match>
        <Match when={route() === 'profile'}>
          <h1>Your Profile</h1>
        </Match>
        <Match when={route() === 'settings'}>
          <h1>Settings</h1>
        </Match>
      </Switch>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
